	subroutine decayWpll_NLO(amp, i1, i2, i3)
	use global_virt
	use basic_funcs_FC6
	implicit none
	double complex amp(2), Fx1
	integer i1, i2, i3

#include "vars.h"

	Fx1 = Hel(i2)*SxS(DottedSpinor(i3,1,7),VxS(e(i1),Spinor(i2,-1,7)))
	amp(1) = EL*Fx1/(SW*Sqrt(2.D0))
        amp(2) = 0
C counter term
        amp(2) = amp(2) + 
     &   1/(2.D0*SW2)*(EL*Fx1*
     &       (-2*dSW1*SW + 2*SW2*dZe1 + SW2*dZW1 + 
     &         SW2*(DCONJG(dZfL1(1,1,1)) + dZfL1(2,1,1))))/
     &     (SW*Sqrt(2.D0))
C loop
        amp(2) = amp(2) + 
     &   Alfa/(16.D0*CW2*Pi*SW2)*
     &    (EL*Fx1*(xrat - 2*Bval(bb0,iinw1) + 4*Cval(cc00,iinw6) + 
     &         SW2*(-2*xrat + 4*Bval(bb0,iinw1) - 
     &            8*Cval(cc00,iinw6)) + 
     &         MW2*(2*Cval(cc0,iinw6) + 2*Cval(cc1,iinw6) + 
     &            SW2*(-4*Cval(cc0,iinw6) - 4*Cval(cc1,iinw6))) + 
     &         CW2*(-4*xrat + 4*Bval(bb0,iinw1) + 
     &            4*Bval(bb0,iinw2) + 8*Cval(cc00,iinw3) + 
     &            8*Cval(cc00,iinw4) + 
     &            SW2*(-16*Cval(cc00,iinw3) + 
     &               16*Cval(cc00,iinw5)) + 
     &            MZ2*(4*Cval(cc0,iinw3) - 
     &               8*SW2*Cval(cc0,iinw3)) + 
     &            MW2*(4*Cval(cc0,iinw4) - 4*Cval(cc1,iinw4) - 
     &               4*Cval(cc2,iinw3) + 
     &               SW2*(8*Cval(cc0,iinw5) + 8*Cval(cc1,iinw5) + 
     &                  8*Cval(cc2,iinw3) + 8*Cval(cc2,iinw5))))))/
     &     (SW*Sqrt(2.D0))


#ifdef DEBUG
	DEB 'decayWll: vec =', vec(1,1,1,i2), Hel(i2)
	DEB 'decayWll LO: amp(1) =', amp(1)
	DEB 'decayWll NLO: amp(2) =', amp(2)
c	stop
#endif

	end
